1	export type Cell = [number, number];
2	
3	const isSameCell = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
4	  x === otherX && y === otherY;
5	
6	const isNeighborOf = (cell: Cell, candidate: Cell): boolean => {
7	  const [x, y] = cell;
8	  const [candidateX, candidateY] = candidate;
9	  return (
10	    Math.abs(candidateX - x) <= 1 &&
11	    Math.abs(candidateY - y) <= 1 &&
12	    !isSameCell(cell, candidate)
13	  );
14	};
15	
16	const countLiveNeighbors = (cell: Cell, liveCells: Cell[]): number =>
17	  liveCells.filter((candidate) => isNeighborOf(cell, candidate)).length;
18	
19	export function nextGeneration(liveCells: Cell[]): Cell[] {
20	  return liveCells.filter((cell) => {
21	    const neighborCount = countLiveNeighbors(cell, liveCells);
22	    return neighborCount === 2 || neighborCount === 3;
23	  });
24	}
